insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('MU', 'default', 'Mauritius reference chart of accounts', '{"fr":"Plan comptable de référence de Maurice"}'::jsonb, true, 'companies', array['MU-IFRS-IS', 'MU-IFRS-SFP']::text[], null, 'There is no legal chart of accounts in Mauritius. Financial Reporting Act 2004, s. 72 — the Financial Reporting Council issues the financial reporting and accounting standards and keeps them consistent with the International Financial Reporting Standards; s. 75(1) — the financial statements of a public interest entity comply with IFRS; the Council''s own framework page adds that the other companies prepare theirs under standards consistent with IFRS (Companies Act 2001, s. 211), and that a company which is not a public interest entity may apply IFRS for SMEs. This chart is original: four digits, blocked so that each range reaches one line of the IFRS-style statements below, with the accounts a Mauritian company actually keeps — VAT input and output tax, import VAT owed to the Mauritius Revenue Authority at the border, PAYE, National Pension Fund, National Savings Fund and Contribution Sociale Généralisée contributions, the HRDC levy and the Corporate Social Responsibility fund.', 'frc-framework')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

