insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('MU', 'MU-P-15', 'Purchase, standard rate 15 %, deductible', '{"fr":"Achat, taux normal 15 %, déductible"}'::jsonb, 'A local purchase of goods or services at the standard rate, used to make taxable supplies', 'percent', 15, 'purchase', 'domestic', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 21(1) and (3)(a) — a taxable person takes the input tax allowable in the taxable period as a credit against output tax, in full where the goods or services are used to make taxable supplies; s. 21(5) — the credit needs a VAT invoice from a supplier authorised to charge VAT. Form VAT 3, line 6.6 — Other goods and services purchased locally.', 'S', null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-P-15-BL', 'Purchase, standard rate 15 %, input tax not allowed', '{"fr":"Achat, taux normal 15 %, TVA non déductible"}'::jsonb, 'A motor car for up to nine persons, accommodation, catering, entertainment and similar items on which section 21(2) refuses the credit', 'percent', 15, 'purchase', 'domestic', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 21(2) — no input tax is allowed as a credit on motor cars and other vehicles for the transport of not more than nine persons including the driver, motorcycles and mopeds for own use (paragraph (b)) and their maintenance and repairs (paragraph (d)); accommodation or lodging, catering services, receptions and entertainment (paragraph (c)); petroleum oils of heading 27.10 other than fuel oils and oils for resale (paragraph (e)); and, since 1 January 2026, the supply of digital or electronic services (paragraph (i), added by the Finance (Miscellaneous Provisions) Act 2025). The VAT is part of the cost of the line. Form VAT 3, line 7 — Taxable input on which no input tax is allowed as a credit. The form asks for the value inclusive of VAT for paragraph (a) goods; this pack reports the value excluding VAT, a gap recorded in the README.', 'S', null, 130, 'vat', false, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-P-15-CAP', 'Purchase of capital goods, standard rate 15 %, deductible', '{"fr":"Achat de biens d''investissement, taux normal 15 %, déductible"}'::jsonb, 'Goods of a capital nature bought locally for the business', 'percent', 15, 'purchase', 'domestic', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 21(1) and (3)(a); the VAT 3 notes for completion distinguish goods of a capital nature purchased locally. A repayment of the excess is claimable at line 15 when the input tax on capital goods exceeds Rs 100,000 (VAT FAQ). Form VAT 3, line 6.4 — Capital goods purchased locally.', 'S', null, 120, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-P-EX', 'Purchase, exempt', '{"fr":"Achat, exonéré"}'::jsonb, 'An insurance premium, a bank service or another exempt supply bought for the business', 'percent', 0, 'purchase', 'exempt', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 9 and First Schedule — an exempt supply carries no VAT. Form VAT 3, line 8.2 — Exempt input, goods and services purchased locally.', 'E', null, 160, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-P-IMP', 'Import of goods, VAT paid at the border', '{"fr":"Importation de biens, TVA payée à la frontière"}'::jsonb, 'Goods imported for the business; the VAT is collected on importation and claimed as input tax', 'percent', 15, 'purchase', 'import', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 10(1)(b) — VAT is charged on the importation of any goods other than those in the First Schedule, by reference to the value determined under s. 13; s. 21(5)(b) — the customs import declaration supports the credit. Form VAT 3, line 6.3 — Other imports. The VAT is held on the import control account until it is settled to the Mauritius Revenue Authority.', null, null, 170, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-P-IMP-CAP', 'Import of capital goods, VAT paid at the border', '{"fr":"Importation de biens d''investissement, TVA payée à la frontière"}'::jsonb, 'Goods of a capital nature imported for the business', 'percent', 15, 'purchase', 'import', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 10(1)(b) and s. 21(1). Form VAT 3, line 6.1 — Capital goods imported, which includes goods on which VAT payment has been deferred; the Deferred Payment Scheme itself (line 2) is not modelled, see the README.', null, null, 180, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-P-IMP-EX', 'Import of exempt goods', '{"fr":"Importation de biens exonérés"}'::jsonb, 'Goods imported that the First Schedule exempts', 'percent', 0, 'purchase', 'import', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 10(1)(b) — goods in the First Schedule bear no VAT on importation. Form VAT 3, line 8.1 — Exempt input, imported goods.', null, null, 200, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-P-IMP-ZR', 'Import of zero-rated goods', '{"fr":"Importation de biens à taux zéro"}'::jsonb, 'Goods imported that the Fifth Schedule zero-rates', 'percent', 0, 'purchase', 'import', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 11 and Fifth Schedule. Form VAT 3, line 6.2 — Zero-rated imports.', null, null, 190, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-P-NR', 'Purchase from a supplier not registered for VAT', '{"fr":"Achat auprès d''un fournisseur non immatriculé à la TVA"}'::jsonb, 'A purchase from a person who is not a registered person and charges no VAT', 'percent', 0, 'purchase', 'not_subject', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 20(5) — no person may issue a document indicating an amount that purports to be VAT unless registered; no input tax can arise on such a purchase. Form VAT 3, line 7(b) — purchases from non VAT registered persons.', 'O', null, 140, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-P-RC-SVC', 'Service received from abroad, self-charged and claimed', '{"fr":"Service reçu de l''étranger, autoliquidé et déduit"}'::jsonb, 'A taxable service supplied by a person who does not belong in Mauritius and is not VAT registered, performed or used in Mauritius', 'percent', 15, 'purchase', 'foreign_services_received', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 14(1) to (4) — the registered recipient is treated as having supplied the services itself, accounts for the output tax and may claim it as input tax under s. 21; the supplier''s invoice is treated as a VAT invoice and the value is the amount paid or payable. Form VAT 3, line 1.4 (supplies of services received from abroad, reverse charge) for the value and the output tax, line 6.6 for the input tax. A foreign supplier of digital or electronic services registers and charges Mauritian VAT itself from 1 January 2026 (s. 14A), which is an ordinary purchase and not this tax; the input tax on that supply is refused by s. 21(2)(i).', null, null, 210, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-P-ZR', 'Purchase, zero-rated', '{"fr":"Achat, taux zéro"}'::jsonb, 'A local purchase of a good or service the Fifth Schedule zero-rates, from a registered supplier', 'percent', 0, 'purchase', 'domestic', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 11 and Fifth Schedule — the supply is a taxable supply at a rate of nil, so the buyer carries no input tax. Form VAT 3, line 6.5 — Zero-rated goods and services purchased locally.', 'Z', null, 150, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-S-15', 'Sale, standard rate 15 %', '{"fr":"Vente, taux normal 15 %"}'::jsonb, 'A taxable supply of goods or services made in Mauritius by a registered person and neither zero-rated nor exempt', 'percent', 15, 'sale', 'domestic', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 4 and s. 10(1) with the Fourth Schedule — VAT is chargeable on every taxable supply made in Mauritius by a taxable person in the course of a business, at fifteen per cent; the FAQ of the Mauritius Revenue Authority adds that a standard-rated supply is any taxable supply that is neither exempt (First Schedule) nor zero-rated (Fifth Schedule). Form VAT 3, line 1.4 — Other taxable supplies. Time of supply: s. 5(1), the earlier of the invoice and the receipt of payment.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-S-EX', 'Sale, exempt', '{"fr":"Vente, exonérée"}'::jsonb, 'A supply of a good or service the First Schedule exempts — residential letting over 90 days, education, banking and insurance services, land and residential property', 'percent', 0, 'sale', 'exempt', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 9 and First Schedule — an exempt supply is not a taxable supply, carries no output VAT and gives no right to deduct the input tax of the goods and services used to make it (s. 21(2)(a)); examples are item 16 educational services, item 46 the letting of residential accommodation for a continuous term over 90 days, item 48 the sale of immovable property, item 50 financial services and item 50(f) insurance. A person who makes only exempt supplies cannot register. Form VAT 3, line 3 — Exempt supplies.', 'E', null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-S-ZR-DOM', 'Sale, zero-rated (local supply)', '{"fr":"Vente, taux zéro (opération locale)"}'::jsonb, 'A supply on the local market of a good or service the Fifth Schedule zero-rates — staple foods, medical and hospital services, public transport, hairdressing and the like', 'percent', 0, 'sale', 'domestic', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 11 and Fifth Schedule — a supply of a description listed there is zero-rated although it never leaves Mauritius: among others rice, wheat flour and bread (item 2), the transport of passengers by public service vehicles (item 38), medical, hospital and dental services (item 42, replaced from 5 August 2021) and hairdressing services (item 62, added by the Finance (Miscellaneous Provisions) Act 2025 and deemed in force from 6 June 2025). The pack carries one tax code for the whole list; which item applies is the preparer''s judgement and is not a field of the format. Form VAT 3, line 1.2 — Zero-rated supplies other than exports.', 'Z', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-S-ZR-EXPG', 'Sale, zero-rated (export of goods)', '{"fr":"Vente, taux zéro (exportation de biens)"}'::jsonb, 'Goods exported from Mauritius under Customs control', 'percent', 0, 'sale', 'export', date '2002-07-01', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 11 and Fifth Schedule, item 1 — goods exported from Mauritius under Customs control are zero-rated: the supply stays a taxable supply at a rate of nil, so the input tax of the exporter remains deductible. Form VAT 3, line 1.1 — Zero-rated supplies (exports); the notes for completion name goods exported, goods shipped, supplies to duty-free shops and supplies to licensees in the freeport zone.', 'G', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null),
  ('MU', 'MU-S-ZR-EXPS', 'Sale, zero-rated (export of services)', '{"fr":"Vente, taux zéro (exportation de services)"}'::jsonb, 'A service supplied to a person who belongs outside Mauritius and is outside Mauritius when it is performed, where the service is not consumed in Mauritius', 'percent', 0, 'sale', 'export', date '2025-08-09', null, 'Value Added Tax Act 1998 (consolidated version up to May 2026), s. 11 and Fifth Schedule, item 6(a) and 6(c) — the supply of services to a person who belongs in a country other than Mauritius (no permanent establishment in Mauritius, or an abode outside it) and who is outside Mauritius at the time the services are performed is zero-rated, provided the services are not consumed in Mauritius; the last proviso was added by the Finance (Miscellaneous Provisions) Act 2025 with effect from 9 August 2025 (endnote 501 of the consolidated text). Form VAT 3, line 1.1.', 'G', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'vat-act', null, null, null, null)
