insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('MU', 'MU-VAT3', 'VAT return (form VAT 3)', array['month', 'quarter']::declaration_period[], null, date '2002-07-01', null, 'Value Added Tax Act, s. 22(1) — every registered person submits electronically, after the end of every taxable period, a return in the form the Director-General approves; the Second Schedule sets the turnover limit at Rs 10 million. s. 22(1A) — a registered person whose annual turnover of taxable supplies does not exceed that amount files for each quarter (31 March, 30 June, 30 September and 31 December) and may elect, by irrevocable written notice, to file monthly; above Rs 10 million the taxable period is the month (VAT FAQ). The cadence therefore depends on a fact about the company, its turnover, which is why no `period_default` is declared. The form is VAT 3; this pack carries the lines a document writes into (1.1 to 11) and not lines 12 to 19, which settle one period against the next and are recorded in docs/international.md. A monthly filer also uploads a list of taxable supplies other than retail with invoice number and value (s. 22(1C)), an annex the format cannot write.', true,'last_day_of_month_after_period'::filing_deadline_rule, null, null, 'Value Added Tax Act, s. 22(2)(a) — the tax payable is paid electronically when the return is submitted. The Mauritius Revenue Authority''s e-services page gives the date for a return filed and a payment made electronically: for a quarterly return, at the end of the month following the end of the quarter; for a monthly return, at the end of the following month. The default rule printed on form VAT 3 and in the VAT FAQ is shorter — 20 days after the end of the month or quarter — and the electronic one-month period replaces it where both the filing and the payment are electronic. A date that falls on a Saturday, a Sunday or a public holiday moves to the next working day. The pack retains the electronic date, since s. 22(1) obliges the return to be submitted electronically; the 20-day rule is not representable beside it.', 'vat-return-page', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

