values
  ('MU', 'MU-VAT3', '1a', 'base', 'Line 1.1 — Zero-rated supplies (exports)', '{"fr":"Ligne 1.1 — Livraisons à taux zéro (exportations)"}'::jsonb, 10, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 1.1, column A — export of goods and services, goods shipped, supplies to duty-free shops, to licensees in the freeport zone and the other supplies the notes for completion list under 1.1.', 'vat3-form'),
  ('MU', 'MU-VAT3', '1b', 'base', 'Line 1.2 — Zero-rated supplies other than exports', '{"fr":"Ligne 1.2 — Livraisons à taux zéro autres qu''exportations"}'::jsonb, 20, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 1.2, column A — zero-rated goods and services supplied on the local market (Fifth Schedule).', 'vat3-form'),
  ('MU', 'MU-VAT3', '1c', 'base', 'Line 1.3 — Taxable supplies made to exempt bodies or persons — value', '{"fr":"Ligne 1.3 — Livraisons imposables à des organismes ou personnes exonérés — valeur"}'::jsonb, 30, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 1.3, column A — the value of taxable supplies made to bodies or persons exempted from payment of VAT. Declared and empty: which buyer is an exempt body or person is a fact about the customer the format does not hold, so no tax code posts to it and the preparer enters the line by hand.', 'vat3-form'),
  ('MU', 'MU-VAT3', '1c', 'tax', 'Line 1.3 — Taxable supplies made to exempt bodies or persons — VAT', '{"fr":"Ligne 1.3 — Livraisons imposables à des organismes ou personnes exonérés — TVA"}'::jsonb, 40, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 1.3, column B — declared and empty, for the reason given at the value column.', 'vat3-form'),
  ('MU', 'MU-VAT3', '1d', 'base', 'Line 1.4 — Other taxable supplies — value', '{"fr":"Ligne 1.4 — Autres opérations imposables — valeur"}'::jsonb, 50, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 1.4, column A — supplies of taxable goods and services, including the disposal of taxable capital goods, supplies for private use, donations and gifts, and supplies of services received from abroad (reverse charge), excluding the zero-rated supplies of lines 1.1 to 1.3.', 'vat3-form'),
  ('MU', 'MU-VAT3', '1d', 'tax', 'Line 1.4 — Other taxable supplies — output VAT', '{"fr":"Ligne 1.4 — Autres opérations imposables — TVA collectée"}'::jsonb, 60, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 1.4, column B — the output VAT on the value of column A, at 15 %.', 'vat3-form'),
  ('MU', 'MU-VAT3', '2', 'tax', 'Line 2 — Deferred VAT on importation', '{"fr":"Ligne 2 — TVA différée à l''importation"}'::jsonb, 70, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 2, column B — the VAT deferred on imported capital goods under the VAT Deferred Payment Scheme. Declared and empty: the scheme postpones a payment at the border and has no document of its own in the format; see the README.', 'vat3-form'),
  ('MU', 'MU-VAT3', '3', 'base', 'Line 3 — Exempt supplies', '{"fr":"Ligne 3 — Opérations exonérées"}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 3, column A — the value of exempt goods and services supplied on the local market (First Schedule).', 'vat3-form'),
  ('MU', 'MU-VAT3', '4', 'tax', 'Line 4 — Penalty on excess amount overclaimed', '{"fr":"Ligne 4 — Pénalité sur excédent indûment réclamé"}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 4, column B — the 20 % penalty on an excess amount overclaimed in a previous period, deemed to be output tax and capped at Rs 100,000. Declared and empty: it is an assessment, not the result of a document.', 'vat3-form'),
  ('MU', 'MU-VAT3', '5A', 'total', 'Line 5 — Total, column A (value)', '{"fr":"Ligne 5 — Total, colonne A (valeur)"}'::jsonb, 100, null, array['1a', '1b', '1c:base', '1d:base', '3']::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 5, column A — the total of the values of lines 1.1 to 1.4 and 3; line 2 and line 4 carry VAT only.', 'vat3-form'),
  ('MU', 'MU-VAT3', '5B', 'total', 'Line 5 — Total, column B (output VAT)', '{"fr":"Ligne 5 — Total, colonne B (TVA collectée)"}'::jsonb, 110, null, array['1c:tax', '1d:tax', '2', '4']::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 5, column B — the total of the VAT of lines 1.3, 1.4, 2 and 4; zero-rated and exempt supplies carry none.', 'vat3-form'),
  ('MU', 'MU-VAT3', '6a', 'base', 'Line 6.1 — Capital goods imported — value', '{"fr":"Ligne 6.1 — Biens d''investissement importés — valeur"}'::jsonb, 120, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 6.1, column A — the importation of goods of a capital nature to the business, including goods on which VAT payment has been deferred.', 'vat3-form'),
  ('MU', 'MU-VAT3', '6a', 'tax', 'Line 6.1 — Capital goods imported — input VAT', '{"fr":"Ligne 6.1 — Biens d''investissement importés — TVA déductible"}'::jsonb, 130, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 6.1, column B.', 'vat3-form'),
  ('MU', 'MU-VAT3', '6b', 'base', 'Line 6.2 — Zero-rated imports', '{"fr":"Ligne 6.2 — Importations à taux zéro"}'::jsonb, 140, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 6.2 — the importation of zero-rated goods.', 'vat3-form'),
  ('MU', 'MU-VAT3', '6c', 'base', 'Line 6.3 — Other imports — value', '{"fr":"Ligne 6.3 — Autres importations — valeur"}'::jsonb, 150, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 6.3, column A — the importation of goods other than capital goods (6.1) and zero-rated goods (6.2).', 'vat3-form'),
  ('MU', 'MU-VAT3', '6c', 'tax', 'Line 6.3 — Other imports — input VAT', '{"fr":"Ligne 6.3 — Autres importations — TVA déductible"}'::jsonb, 160, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 6.3, column B.', 'vat3-form'),
  ('MU', 'MU-VAT3', '6d', 'base', 'Line 6.4 — Capital goods purchased locally — value', '{"fr":"Ligne 6.4 — Biens d''investissement achetés localement — valeur"}'::jsonb, 170, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 6.4, column A — goods of a capital nature to the business purchased locally.', 'vat3-form'),
  ('MU', 'MU-VAT3', '6d', 'tax', 'Line 6.4 — Capital goods purchased locally — input VAT', '{"fr":"Ligne 6.4 — Biens d''investissement achetés localement — TVA déductible"}'::jsonb, 180, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 6.4, column B.', 'vat3-form'),
  ('MU', 'MU-VAT3', '6e', 'base', 'Line 6.5 — Zero-rated goods and services purchased locally', '{"fr":"Ligne 6.5 — Biens et services à taux zéro achetés localement"}'::jsonb, 190, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 6.5 — zero-rated goods and services supplied to the business locally.', 'vat3-form'),
  ('MU', 'MU-VAT3', '6f', 'base', 'Line 6.6 — Other goods and services purchased locally — value', '{"fr":"Ligne 6.6 — Autres biens et services achetés localement — valeur"}'::jsonb, 200, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 6.6, column A — local supplies to the business other than capital goods (6.4) and zero-rated supplies (6.5); a service received from abroad under the reverse charge is also reported here.', 'vat3-form'),
  ('MU', 'MU-VAT3', '6f', 'tax', 'Line 6.6 — Other goods and services purchased locally — input VAT', '{"fr":"Ligne 6.6 — Autres biens et services achetés localement — TVA déductible"}'::jsonb, 210, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 6.6, column B.', 'vat3-form'),
  ('MU', 'MU-VAT3', '7', 'base', 'Line 7 — Taxable input on which no input tax is allowed as a credit', '{"fr":"Ligne 7 — Achats pour lesquels aucun crédit de TVA n''est admis"}'::jsonb, 220, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 7 — (a) imports and purchases in respect of which section 21(2) refuses the credit, which the notes ask to be entered inclusive of VAT, and (b) purchases from persons who are not VAT registered. This pack enters the value excluding VAT, see the README.', 'vat3-form'),
  ('MU', 'MU-VAT3', '8a', 'base', 'Line 8.1 — Exempt input, imported goods', '{"fr":"Ligne 8.1 — Achats exonérés, biens importés"}'::jsonb, 230, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 8.1 — imports of exempt goods.', 'vat3-form'),
  ('MU', 'MU-VAT3', '8b', 'base', 'Line 8.2 — Exempt input, goods and services purchased locally', '{"fr":"Ligne 8.2 — Achats exonérés, biens et services achetés localement"}'::jsonb, 240, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 8.2 — exempt goods and services purchased locally.', 'vat3-form'),
  ('MU', 'MU-VAT3', '9A', 'total', 'Line 9 — Total, column A (value)', '{"fr":"Ligne 9 — Total, colonne A (valeur)"}'::jsonb, 250, null, array['6a:base', '6b', '6c:base', '6d:base', '6e', '6f:base', '7', '8a', '8b']::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 9, column A — the total of the values of lines 6.1 to 6.6, 7, 8.1 and 8.2.', 'vat3-form'),
  ('MU', 'MU-VAT3', '9B', 'total', 'Line 9 — Total, column B (input VAT)', '{"fr":"Ligne 9 — Total, colonne B (TVA déductible)"}'::jsonb, 260, null, array['6a:tax', '6c:tax', '6d:tax', '6f:tax']::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 9, column B — the total of the VAT of lines 6.1, 6.3, 6.4 and 6.6.', 'vat3-form'),
  ('MU', 'MU-VAT3', '10', 'total', 'Line 10 — Input tax deductible', '{"fr":"Ligne 10 — TVA déductible"}'::jsonb, 270, null, array['9B']::text[], '{}'::text[], null, null, false, false, null, 'Form VAT 3, line 10, column B — the input tax allowed as a credit. Section 21(3)(b) apportions the input tax of a person who makes both taxable and exempt supplies by the proportion of taxable supplies to total turnover of the previous accounting year (the percentage printed at the head of the input section); this pack carries no such proportion and reports the whole of line 9B, which is the figure a wholly taxable business files. The apportionment is recorded in the README.', 'vat3-form'),
  ('MU', 'MU-VAT3', '11', 'total', 'Line 11 — VAT due and payable / (Excess VAT)', '{"fr":"Ligne 11 — TVA à payer / (crédit de TVA)"}'::jsonb, 280, null, array['5B']::text[], array['10']::text[], null, null, false, false, null, 'Form VAT 3, line 11 — line 5B minus line 10B. A positive figure is payable to the Mauritius Revenue Authority with the return; a negative figure is an excess carried forward on line 12 of the next return or claimed for repayment on line 15 (s. 22(2)(b) and s. 24). Lines 12 to 19 — the excess brought forward, adjustments, the repayment claim, the penalties and interest — are period-to-period settlement and assessment, not the result of a document, and are not carried.', 'vat3-form')
