update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = null,
  late_payment_reference        = null,
  numbering_legal_reference     = 'Value Added Tax Act, s. 20(2)(a) to (c) — a VAT invoice carries the words "VAT INVOICE" in a prominent place, the supplier''s name, address, VAT registration number and business registration number, its serial number and its date of issue; s. 20(3) — legible copies are kept in chronological order, and s. 20(4) for at least five years. The law asks for a serial number and not for a series without a gap, which is why the style is `sequential`. The fiscal invoice of the e-invoicing system carries, in addition, the Invoice Registration Number the Mauritius Revenue Authority''s platform issues (Value Added Tax (E-invoicing) Regulations 2023, reg. 2 and 5(e)), which this pack cannot generate.',
  numbering_source_key          = 'vat-act',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_date',
  tax_point_legal_reference     = 'Value Added Tax Act, s. 5(1) — a supply of goods or services is deemed to take place at the time an invoice or VAT invoice for it is issued by the supplier or at the time payment is received by the supplier, whichever is the earlier; s. 5(2) applies the same rule to each successive part of a continuous supply of services. The closed vocabulary has no word for "the earlier of the invoice and the payment": `invoice_date` is the principle, and a payment received before the invoice, which brings the tax point forward in Mauritius, is the gap recorded in docs/international.md.',
  tax_point_source_key          = 'vat-act',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_obligation           = 'none',
  einvoice_legal_reference      = 'Mauritius has no Peppol profile, no published structured-invoice standard and no ISO 6523 scheme a party is addressed by, so `profile`, `party_scheme` and `vat_scheme` are null and `obligation` is `none`: what Mauritius has instead is a real-time fiscalisation (clearance) system, which the vocabulary of this field does not describe. Value Added Tax Act, s. 20A(1) — the Director-General sets up an e-invoicing system through which a business registers every invoice, debit note and credit note and issues fiscal invoices to its customers; s. 20A(2) — a person who carries on a business activity of a prescribed category, or who is notified in writing by the Director-General, acquires the equipment and software and issues fiscal invoices from the date the Director-General fixes, whether or not it is a taxable person (s. 20A(3)); ss. 20B and 20C — a penalty of Rs 10,000 per month, capped at Rs 200,000, for failing to issue fiscal invoices, and up to Rs 50,000 for tampering. The Value Added Tax (E-invoicing) Regulations 2023 (Government Notice No. 132 of 2023, in force 2 October 2023) require an Electronic Billing System to send each transaction to the Invoice Fiscalisation Platform and to print on the fiscal invoice the Invoice Registration Number and the QR code the platform returns. The Authority''s roll-out table lists limited companies above Rs 100 million of annual turnover from 15 May 2024, and the other taxpayers above Rs 100 million from 1 August 2025, above Rs 80 million from 30 June 2026 and above Rs 40 million from 1 September 2026, each marked as launched. Ekwo does not call the platform and issues no Invoice Registration Number: a company in scope fiscalises through a certified Electronic Billing System, and the gap is recorded in docs/international.md and in the README of this pack.',
  einvoice_source_key           = 'einvoicing-regs',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'MU';

